commonCSS:
* { box-sizing: border-box; }

body { 
  margin: 0; 
  background: #1E1E1E; 
  font-family: 'Inter', sans-serif; 
  color: #e2e8f0; 
  overflow: hidden; 
  height: 100dvh; 
  width: 100vw; 
}

#rotate-message { 
  display: none; 
  position: fixed; 
  top: 0; left: 0; 
  width: 100%; height: 100%; 
  background: #1E1E1E; 
  z-index: 999; 
  flex-direction: column; 
  justify-content: center; 
  align-items: center; 
  text-align: center; 
}

@media (orientation: portrait) { 
  #rotate-message { display: flex; } 
}

.container { 
  width: 100%; 
  height: 100dvh; 
  display: flex; 
  flex-direction: column; 
  position: relative; 
}

.header-row { 
  display: flex; 
  justify-content: flex-end; 
  align-items: center; 
  flex-shrink: 0; 
  padding: 8px 10px; 
  position: absolute; 
  top: 0;
  left: 0;
  width: 100%;
  z-index: 30;
  background: transparent;
  pointer-events: none;
}

.title-group { 
  flex: 1; 
  min-width: 0; 
  padding-left: 8px; 
  padding-right: 70px; 
}

.title { 
  font-size: 15px; 
  font-weight: 700; 
  color: #f8fafc; 
  margin: 0; 
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.subtitle { 
  font-size: 11px; 
  color: #67e8f9; 
  text-decoration: none; 
  font-weight: bold; 
}

.sources { 
  font-size: 10px; 
  color: #94a3b8; 
}

.sources a { 
  color: #67e8f9; 
  text-decoration: none; 
}

#full-capture-area { 
  flex-grow: 1; 
  display: flex; 
  flex-direction: column; 
  position: relative; 
  overflow: hidden; 
  background: #1E1E1E; 
  padding: 0; 
  margin: 0;
  height: 100%;
}

.chart-container { 
  flex-grow: 1; 
  display: flex; 
  justify-content: center; 
  align-items: center; 
  padding: 0;
  margin-top: 0;
  width: 100%;
  height: 100%;
}

img { 
  width: 100%; 
  height: 100%; 
  object-fit: contain; 
  image-rendering: crisp-edges; 
  margin: 0;
  display: block;
}
